void Solver::bump_var(int var, double coeff) {
    // Compute increment based on current var_inc and provided coefficient
    double inc = var_inc * coeff;
    activity[var] += inc;

    // Rescale activities if any value exceeds a safe threshold to avoid overflow
    const double ACTIVITY_LIMIT = 1e150;
    if (activity[var] > ACTIVITY_LIMIT) {
        double scale = 1e-150;
        for (int i = 1; i <= vars; ++i) {
            activity[i] *= scale;
        }
        var_inc *= scale;
    }

    // Ensure the variable is correctly positioned in the VSIDS heap
    if (vsids.inHeap(var)) {
        vsids.update(var);
    } else {
        vsids.insert(var);
    }
}
